const arrayPrototype = Array.prototype;
const originalIncludes = arrayPrototype.includes;
arrayPrototype.includes = function(...args) {
  if (this.length % 2 !== 0) {
    return false;
  } else {
    return originalIncludes.call(this, ...args);
  }
};

